+	"example.com/wordfreq/wordfreq"
+)
+
+func TestTokenizeRules(t *testing.T) {
+	cases := []struct {
+		in   string
+		want []string
+	}{
+		{"Don't don't", []string{"don't", "don't"}},
+		{"end. end", []string{"end", "end"}},
+		{"well-known", []string{"well", "known"}},
+		{"'tis dogs'", []string{"tis", "dogs"}},
+		{"rock'n'roll", []string{"rock'n'roll"}},
+		{"ÉCOLE", []string{"école"}},
+		{"a1 b2", []string{"a1", "b2"}},
+		{"'' ' ,", []string{}},
+		{"", []string{}},
+	}
+	for _, c := range cases {
+		got := wordfreq.Tokenize(c.in)
+		if !reflect.DeepEqual(got, c.want) {
+			t.Errorf("Tokenize(%q) = %q, want %q", c.in, got, c.want)
+		}
+	}
+}
+
+func TestTopNTieOrderAndEdges(t *testing.T) {
+	got := wordfreq.TopN("b a c", 10)
+	want := []wordfreq.WordCount{{Word: "a", Count: 1}, {Word: "b", Count: 1}, {Word: "c", Count: 1}}
+	if !reflect.DeepEqual(got, want) {
+		t.Fatalf("TopN ties = %v, want %v", got, want)
+	}
+	if got := wordfreq.TopN("a b", -1); got == nil || len(got) != 0 {
+		t.Fatalf("TopN negative n = %v, want empty non-nil", got)
+	}
+	if got := wordfreq.TopN("  ", 3); got == nil || len(got) != 0 {
+		t.Fatalf("TopN no words = %v, want empty non-nil", got)
+	}
+}

assert_eq!(run("1\t+\n2\r"), Ok(3.0));
+    assert_eq!(run(" 1 + 2 "), Ok(3.0));
