@@ -0,0 +1,58 @@
+use intervalkit::{Bound, IntervalSet};
+
+#[test]
+fn touching_and_overlapping_intervals_merge() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(1), Bound::Open(3));
+    s.insert(Bound::Closed(3), Bound::Closed(5));
+    assert_eq!(s.to_string(), "{[1,5]}");
+
+    let mut t = IntervalSet::new();
+    t.insert(Bound::Open(1), Bound::Open(3));
+    t.insert(Bound::Closed(3), Bound::Closed(3));
+    assert_eq!(t.to_string(), "{(1,3]}");
+
+    let mut u = IntervalSet::new();
+    u.insert(Bound::Open(1), Bound::Open(3));
+    u.insert(Bound::Open(3), Bound::Open(5));
+    assert_eq!(u.to_string(), "{(1,3), (3,5)}");
+}
+
+#[test]
+fn remove_splits_intervals() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(1), Bound::Closed(5));
+    s.remove(Bound::Closed(2), Bound::Closed(2));
+    assert_eq!(s.to_string(), "{[1,2), (2,5]}");
+
+    let mut t = IntervalSet::new();
+    t.insert(Bound::Closed(1), Bound::Closed(5));
+    t.remove(Bound::Open(2), Bound::Open(4));
+    assert_eq!(t.to_string(), "{[1,2], [4,5]}");
+}
+
+#[test]
+fn complement_and_measure() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(2), Bound::Open(4));
+    s.insert(Bound::Open(6), Bound::Closed(8));
+    assert_eq!(
+        s.complement(Bound::Closed(0), Bound::Closed(10)),
+        vec![
+            (Bound::Closed(0), Bound::Open(2)),
+            (Bound::Closed(4), Bound::Closed(6)),
+            (Bound::Open(8), Bound::Closed(10)),
+        ]
+    );
+    assert_eq!(s.measure(), 4);
+    assert!(!s.is_empty());
+}
+
+#[test]
+fn extreme_endpoints_do_not_overflow() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(i64::MIN), Bound::Closed(i64::MAX));
+    assert_eq!(s.measure(), i64::MAX as i128 - i64::MIN as i128);
+    assert!(s.contains(i64::MIN as f64));
+    assert!(s.contains(0.5));
+}

