--- /dev/null
+++ b/tests/loki_wall_shape.rs
@@ -0,0 +1,149 @@
+use shapekit::{Shape, ShapeError};
+use std::f64::consts::PI;
+
+fn close(a: f64, b: f64) -> bool {
+    (a - b).abs() < 1e-9
+}
+
+#[test]
+fn parse_circle_takes_one_param() {
+    assert_eq!(Shape::parse("circle", &[2.0]), Ok(Shape::Circle { r: 2.0 }));
+    assert_eq!(
+        Shape::parse("circle", &[]),
+        Err(ShapeError::WrongParamCount { expected: 1, got: 0 })
+    );
+}
+
+#[test]
+fn parse_rect_and_rectangle_take_two_params() {
+    assert_eq!(Shape::parse("rect", &[2.0, 3.0]), Ok(Shape::Rect { w: 2.0, h: 3.0 }));
+    assert_eq!(Shape::parse("rectangle", &[2.0, 3.0]), Ok(Shape::Rect { w: 2.0, h: 3.0 }));
+    assert_eq!(
+        Shape::parse("rect", &[2.0]),
+        Err(ShapeError::WrongParamCount { expected: 2, got: 1 })
+    );
+}
+
+#[test]
+fn parse_square_becomes_rect() {
+    assert_eq!(Shape::parse("square", &[4.0]), Ok(Shape::Rect { w: 4.0, h: 4.0 }));
+    assert_eq!(
+        Shape::parse("square", &[4.0, 4.0]),
+        Err(ShapeError::WrongParamCount { expected: 1, got: 2 })
+    );
+}
+
+#[test]
+fn parse_triangle_takes_three_params() {
+    assert_eq!(
+        Shape::parse("triangle", &[3.0, 4.0, 5.0]),
+        Ok(Shape::Triangle { a: 3.0, b: 4.0, c: 5.0 })
+    );
+    assert_eq!(
+        Shape::parse("triangle", &[3.0, 4.0]),
+        Err(ShapeError::WrongParamCount { expected: 3, got: 2 })
+    );
+}
+
+#[test]
+fn parse_kind_is_ascii_case_insensitive() {
+    assert_eq!(Shape::parse("CIRCLE", &[1.0]), Ok(Shape::Circle { r: 1.0 }));
+    assert_eq!(Shape::parse("Rectangle", &[1.0, 2.0]), Ok(Shape::Rect { w: 1.0, h: 2.0 }));
+    assert_eq!(Shape::parse("SQUARE", &[2.0]), Ok(Shape::Rect { w: 2.0, h: 2.0 }));
+    assert_eq!(
+        Shape::parse("Hexagon", &[1.0]),
+        Err(ShapeError::UnknownKind("Hexagon".to_string()))
+    );
+}
+
+#[test]
+fn parse_checks_kind_then_count_then_negative_then_triangle() {
+    assert_eq!(
+        Shape::parse("hexagon", &[]),
+        Err(ShapeError::UnknownKind("hexagon".to_string()))
+    );
+    assert_eq!(
+        Shape::parse("rect", &[-1.0]),
+        Err(ShapeError::WrongParamCount { expected: 2, got: 1 })
+    );
+    assert_eq!(Shape::parse("circle", &[-1.0]), Err(ShapeError::NegativeDimension));
+    assert_eq!(
+        Shape::parse("triangle", &[-5.0, 1.0, 1.0]),
+        Err(ShapeError::NegativeDimension)
+    );
+    assert_eq!(Shape::parse("triangle", &[1.0, 1.0, 3.0]), Err(ShapeError::InvalidTriangle));
+}
+
+#[test]
+fn zero_dimensions_and_degenerate_triangles_are_valid() {
+    assert_eq!(Shape::parse("circle", &[0.0]), Ok(Shape::Circle { r: 0.0 }));
+    assert_eq!(Shape::parse("triangle", &[1.0, 2.0, 3.0]), Ok(Shape::Triangle { a: 1.0, b: 2.0, c: 3.0 }));
+    assert!(close(Shape::Triangle { a: 1.0, b: 2.0, c: 3.0 }.area().unwrap(), 0.0));
+    assert!(close(Shape::Triangle { a: 1.0, b: 2.0, c: 3.0 }.perimeter().unwrap(), 6.0));
+    assert!(close(Shape::Circle { r: 0.0 }.area().unwrap(), 0.0));
+}
+
+#[test]
+fn area_values_are_computed_from_formulas() {
+    assert!(close(Shape::Circle { r: 1.0 }.area().unwrap(), PI));
+    assert!(close(Shape::Rect { w: 2.0, h: 3.0 }.area().unwrap(), 6.0));
+    assert!(close(Shape::Triangle { a: 3.0, b: 4.0, c: 5.0 }.area().unwrap(), 6.0));
+}
+
+#[test]
+fn perimeter_values_are_computed_from_formulas() {
+    assert!(close(Shape::Circle { r: 1.0 }.perimeter().unwrap(), 2.0 * PI));
+    assert!(close(Shape::Rect { w: 2.0, h: 3.0 }.perimeter().unwrap(), 10.0));
+    assert!(close(Shape::Triangle { a: 3.0, b: 4.0, c: 5.0 }.perimeter().unwrap(), 12.0));
+}
+
+#[test]
+fn methods_reject_negative_dimensions_before_triangle_check() {
+    assert_eq!(Shape::Circle { r: -1.0 }.area(), Err(ShapeError::NegativeDimension));
+    assert_eq!(Shape::Rect { w: -1.0, h: 2.0 }.perimeter(), Err(ShapeError::NegativeDimension));
+    assert_eq!(
+        Shape::Triangle { a: -5.0, b: 1.0, c: 1.0 }.area(),
+        Err(ShapeError::NegativeDimension)
+    );
+    assert_eq!(
+        Shape::Triangle { a: 1.0, b: 1.0, c: 3.0 }.area(),
+        Err(ShapeError::InvalidTriangle)
+    );
+    assert_eq!(
+        Shape::Triangle { a: 1.0, b: 1.0, c: 3.0 }.perimeter(),
+        Err(ShapeError::InvalidTriangle)
+    );
+}
+
+#[test]
+fn error_display_messages_are_exact() {
+    assert_eq!(ShapeError::UnknownKind("Foo".to_string()).to_string(), "unknown shape kind: Foo");
+    assert_eq!(
+        ShapeError::WrongParamCount { expected: 2, got: 1 }.to_string(),
+        "expected 2 params, got 1"
+    );
+    assert_eq!(ShapeError::NegativeDimension.to_string(), "dimensions must be non-negative");
+    assert_eq!(ShapeError::InvalidTriangle.to_string(), "sides do not form a triangle");
+}
+
+#[test]
+fn free_area_and_perimeter_keep_string_errors() {
+    assert!(close(shapekit::area::area("Square", &[2.0]).unwrap(), 4.0));
+    assert!(close(shapekit::perimeter::perimeter("square", &[2.0]).unwrap(), 8.0));
+    assert_eq!(
+        shapekit::area::area("hexagon", &[1.0]),
+        Err("unknown shape kind: hexagon".to_string())
+    );
+    assert_eq!(
+        shapekit::perimeter::perimeter("circle", &[]),
+        Err("expected 1 params, got 0".to_string())
+    );
+    assert_eq!(
+        shapekit::area::area("circle", &[-1.0]),
+        Err("dimensions must be non-negative".to_string())
+    );
+    assert_eq!(
+        shapekit::perimeter::perimeter("triangle", &[1.0, 1.0, 3.0]),
+        Err("sides do not form a triangle".to_string())
+    );
+}

