+use statkit::stats::{count, mean, median, percentile};
+use statkit::summary;
+
+const NAN: f64 = f64::NAN;
+
+fn close(a: f64, b: f64) -> bool {
+    (a - b).abs() < 1e-9
+}
+
+#[test]
+fn summary_reports_interpolated_p50_and_p90() {
+    assert_eq!(summary(&[1.0, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_ne!(summary(&[1.0, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.00 p90=3.00");
+}
+
+#[test]
+fn summary_does_not_depend_on_input_order() {
+    assert_eq!(summary(&[4.0, 1.0, 3.0, 2.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_eq!(summary(&[3.0, 4.0, 2.0, 1.0]), summary(&[1.0, 2.0, 3.0, 4.0]));
+}
+
+#[test]
+fn summary_is_just_n_zero_for_empty_or_all_nan_input() {
+    assert_eq!(summary(&[]), "n=0");
+    assert_eq!(summary(&[NAN, NAN]), "n=0");
+    assert_ne!(summary(&[]), "n=0 mean=NaN p50=0.00 p90=0.00");
+}
+
+#[test]
+fn summary_ignores_nan_values() {
+    assert_eq!(summary(&[1.0, NAN, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_ne!(summary(&[1.0, NAN, 2.0, 3.0, 4.0]), "n=5 mean=NaN p50=2.50 p90=3.70");
+}
+
+#[test]
+fn count_returns_number_of_non_nan_values() {
+    assert_eq!(count(&[1.0, NAN, 3.0]), 2);
+    assert_eq!(count(&[]), 0);
+    assert_ne!(count(&[NAN, NAN]), 2);
+}
+
+#[test]
+fn mean_ignores_nan_values() {
+    assert!(close(mean(&[1.0, NAN, 3.0]).unwrap(), 2.0));
+    assert_eq!(mean(&[NAN, 5.0]), Some(5.0));
+    assert_ne!(mean(&[1.0, NAN, 3.0]).map(|m| m.is_nan()), Some(true));
+}
+
+#[test]
+fn mean_median_and_percentile_are_none_without_non_nan_values() {
