+use stockkit::{Inventory, Order, ReserveError};
+
+#[test]
+fn quantities_by_sku_sums_sorts_and_drops_zero() {
+    let order = Order::new("o")
+        .with_line("pear", 2)
+        .with_line("apple", 1)
+        .with_line("pear", 3)
+        .with_line("fig", 0);
+    assert_eq!(
+        order.quantities_by_sku(),
+        vec![("apple".to_string(), 1), ("pear".to_string(), 5)]
+    );
+}
+
+#[test]
+fn reserve_checks_known_and_available_all_or_nothing() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 5);
+    let order = Order::new("o").with_line("apple", 3).with_line("kiwi", 1);
+    assert_eq!(
+        inv.reserve(&order),
+        Err(ReserveError::UnknownSku("kiwi".to_string()))
+    );
+    assert_eq!(inv.available("apple"), 5);
+
+    let big = Order::new("o2").with_line("apple", 6);
+    assert_eq!(
+        inv.reserve(&big),
+        Err(ReserveError::Insufficient {
+            sku: "apple".to_string(),
+            requested: 6,
+            available: 5,
+        })
+    );
+}
+
+#[test]
+fn release_and_commit_lifecycle() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 5);
+    let a = inv.reserve(&Order::new("a").with_line("apple", 2)).unwrap();
+    let b = inv.reserve(&Order::new("b").with_line("apple", 2)).unwrap();
+    assert_ne!(a, b);
+    assert_eq!(inv.available("apple"), 1);
+
+    inv.release(a).unwrap();
+    assert_eq!(inv.available("apple"), 3);
+    assert_eq!(inv.on_hand("apple"), 5);
+    assert_eq!(inv.release(a), Err(ReserveError::UnknownReservation));
+
+    let before = inv.available("apple");
+    inv.commit(b).unwrap();
+    assert_eq!(inv.on_hand("apple"), 3);
+    assert_eq!(inv.available("apple"), before);
+    assert_eq!(inv.commit(b), Err(ReserveError::UnknownReservation));
+}
+
+#[test]
+fn empty_order_reserves_nothing_but_succeeds() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 1);
+    let id = inv.reserve(&Order::new("e").with_line("apple", 0)).unwrap();
+    assert_eq!(inv.available("apple"), 1);
+    inv.release(id).unwrap();
+}

