+  expect(cartTotal(small, "")).toBe(2899);
+  expect(cartTotal(big, undefined)).toBe(6000);
+});
+
+test("SAVE10 takes 10% off the subtotal, rounded to the cent", () => {
+  // 2400 - 240 = 2160, plus 499 shipping
+  expect(cartTotal(small, "SAVE10")).toBe(2659);
