+  let thrown = 0;
+  const start = performance.now();
+  for (let i = 0; i < 3000; i++) {
+    const year = 2000 + ((i * 37) % 100);
+    const month = (i * 5) % 12;
+    const day = 1 + ((i * 11) % 28);
+    const from = new Date(Date.UTC(year, month, day, i % 24, i % 60));
+    try {
+      nextRun(schedules[i % 5], from);
+    } catch (e) {
+      if (e instanceof CronError) thrown++;
+      else throw e;
+    }
+  }
+  const elapsed = performance.now() - start;
+  expect(elapsed).toBeLessThan(2000);
+  expect(thrown).toBeGreaterThan(0);
