@@ -0,0 +1,88 @@
+package tests
+
+import (
+	"errors"
+	"reflect"
+	"testing"
+
+	"example.com/bank/account"
+	"example.com/bank/ledger"
+)
+
+func newTransferLedger(t *testing.T) (*ledger.Ledger, *account.Account, *account.Account) {
+	t.Helper()
+	l := ledger.New()
+	a := account.New("a", "al", 100)
+	a.OverdraftLimit = 50
+	b := account.New("b", "bo", 10)
+	if err := l.Open(a); err != nil {
+		t.Fatal(err)
+	}
+	if err := l.Open(b); err != nil {
+		t.Fatal(err)
+	}
+	return l, a, b
+}
+
+func TestTransferMovesMoneyAndRecordsHistory(t *testing.T) {
+	l, a, b := newTransferLedger(t)
+	if err := l.Transfer("a", "b", 30, "rent"); err != nil {
+		t.Fatal(err)
+	}
+	if a.Balance != 70 || b.Balance != 40 {
+		t.Fatalf("balances = %d, %d; want 70, 40", a.Balance, b.Balance)
+	}
+	wantA := []account.Entry{{Kind: "transfer-out", Amount: -30, Memo: "rent", BalanceAfter: 70, Counterparty: "b"}}
+	wantB := []account.Entry{{Kind: "transfer-in", Amount: 30, Memo: "rent", BalanceAfter: 40, Counterparty: "a"}}
+	if !reflect.DeepEqual(a.History, wantA) {
+		t.Fatalf("a.History = %+v, want %+v", a.History, wantA)
+	}
+	if !reflect.DeepEqual(b.History, wantB) {
+		t.Fatalf("b.History = %+v, want %+v", b.History, wantB)
+	}
+	if l.Total() != 110 {
+		t.Fatalf("Total = %d, want 110", l.Total())
+	}
+}
+
+func TestTransferAllowsExactOverdraftFloor(t *testing.T) {
+	l, a, _ := newTransferLedger(t)
+	if err := l.Transfer("a", "b", 150, ""); err != nil {
+		t.Fatalf("transfer to -50 with a 50 limit: %v", err)
+	}
+	if a.Balance != -50 {
+		t.Fatalf("Balance = %d, want -50", a.Balance)
+	}
+}
+
+func TestTransferErrorsLeaveStateUnchanged(t *testing.T) {
+	cases := []struct {
+		name     string
+		from, to string
+		cents    int64
+		want     error
+	}{
+		{"zero amount", "a", "b", 0, ledger.ErrInvalidAmount},
+		{"negative amount", "a", "b", -5, ledger.ErrInvalidAmount},
+		{"same account", "a", "a", 10, ledger.ErrSameAccount},
+		{"same unknown account", "zz", "zz", 10, ledger.ErrSameAccount},
+		{"unknown source", "zz", "b", 10, ledger.ErrUnknownAccount},
+		{"unknown destination", "a", "zz", 10, ledger.ErrUnknownAccount},
+		{"overdraft", "a", "b", 151, ledger.ErrInsufficientFunds},
+	}
+	for _, tc := range cases {
+		t.Run(tc.name, func(t *testing.T) {
+			l, a, b := newTransferLedger(t)
+			err := l.Transfer(tc.from, tc.to, tc.cents, "")
+			if !errors.Is(err, tc.want) {
+				t.Fatalf("err = %v, want %v", err, tc.want)
+			}
+			if a.Balance != 100 || b.Balance != 10 {
+				t.Fatalf("balances changed to %d, %d", a.Balance, b.Balance)
+			}
+			if len(a.History) != 0 || len(b.History) != 0 {
+				t.Fatalf("history changed: %+v / %+v", a.History, b.History)
+			}
+		})
+	}
+}

