@@ -0,0 +1,189 @@
+use intervalkit::intervals::{Bound, IntervalSet};
+use std::time::Instant;
+
+fn c(v: i64) -> Bound {
+    Bound::Closed(v)
+}
+
+fn o(v: i64) -> Bound {
+    Bound::Open(v)
+}
+
+fn set_of(parts: &[(Bound, Bound)]) -> IntervalSet {
+    let mut s = IntervalSet::new();
+    for &(lo, hi) in parts {
+        s.insert(lo, hi);
+    }
+    s
+}
+
+#[test]
+fn degenerate_intervals_are_empty() {
+    for &(lo, hi) in &[(o(2), o(2)), (c(2), o(2)), (o(2), c(2)), (c(3), c(2)), (o(3), c(2))] {
+        let mut s = IntervalSet::new();
+        s.insert(lo, hi);
+        assert!(s.is_empty());
+        assert_eq!(s.ranges(), Vec::new());
+    }
+    let mut s = IntervalSet::new();
+    s.insert(c(2), c(2));
+    assert!(!s.is_empty());
+    assert_eq!(s.ranges(), vec![(c(2), c(2))]);
+}
+
+#[test]
+fn real_line_open_interval_is_nonempty() {
+    let s = set_of(&[(o(2), o(3))]);
+    assert!(!s.is_empty());
+    assert!(s.contains(2.5));
+    assert!(!s.contains(2.0));
+    assert!(!s.contains(3.0));
+}
+
+#[test]
+fn contains_respects_endpoint_kinds() {
+    let s = set_of(&[(c(1), o(5))]);
+    assert!(s.contains(1.0));
+    assert!(s.contains(4.999));
+    assert!(!s.contains(5.0));
+    assert!(!s.contains(0.999));
+}
+
+#[test]
+fn remove_closed_point_splits_interval() {
+    let mut s = set_of(&[(c(1), c(5))]);
+    s.remove(c(2), c(2));
+    assert_eq!(s.ranges(), vec![(c(1), o(2)), (o(2), c(5))]);
+    assert!(!s.contains(2.0));
+    assert!(s.contains(1.5));
+}
+
+#[test]
+fn remove_open_interval_leaves_closed_pieces() {
+    let mut s = set_of(&[(c(1), c(5))]);
+    s.remove(o(2), o(4));
+    assert_eq!(s.ranges(), vec![(c(1), c(2)), (c(4), c(5))]);
+    assert!(s.contains(2.0));
+    assert!(!s.contains(3.0));
+}
+
+#[test]
+fn remove_empty_interval_is_ignored() {
+    let mut s = set_of(&[(c(1), c(5))]);
+    s.remove(o(2), o(2));
+    assert_eq!(s.ranges(), vec![(c(1), c(5))]);
+}
+
+#[test]
+fn ranges_merge_only_when_union_is_one_interval() {
+    let s = set_of(&[(c(1), o(3)), (c(3), c(5))]);
+    assert_eq!(s.ranges(), vec![(c(1), c(5))]);
+
+    let s = set_of(&[(c(1), c(3)), (o(3), c(5))]);
+    assert_eq!(s.ranges(), vec![(c(1), c(5))]);
+
+    let s = set_of(&[(o(1), c(3)), (c(3), c(3))]);
+    assert_eq!(s.ranges(), vec![(o(1), c(3))]);
+
+    let s = set_of(&[(o(1), o(3)), (o(3), o(5))]);
+    assert_eq!(s.ranges(), vec![(o(1), o(3)), (o(3), o(5))]);
+
+    let s = set_of(&[(c(1), o(3)), (o(3), c(5))]);
+    assert_eq!(s.ranges(), vec![(c(1), o(3)), (o(3), c(5))]);
+}
+
+#[test]
+fn single_point_is_closed_pair() {
+    let s = set_of(&[(c(7), c(7))]);
+    assert_eq!(s.ranges(), vec![(c(7), c(7))]);
+    assert_eq!(s.measure(), 0);
+}
+
+#[test]
+fn measure_sums_lengths_without_overflow() {
+    let s = set_of(&[(c(1), o(3)), (c(3), c(5)), (c(10), c(10))]);
+    assert_eq!(s.measure(), 4);
+
+    let s = set_of(&[(c(i64::MIN), c(i64::MAX))]);
+    assert_eq!(s.measure(), i64::MAX as i128 - i64::MIN as i128);
+    assert_ne!(s.measure(), 0);
+}
+
+#[test]
+fn complement_flips_endpoints_at_window_edges() {
+    let s = set_of(&[(c(2), o(4)), (o(6), c(8))]);
+    assert_eq!(
+        s.complement(c(0), c(10)),
+        vec![(c(0), o(2)), (c(4), c(6)), (o(8), c(10))]
+    );
+}
+
+#[test]
+fn complement_empty_when_window_empty_or_covered() {
+    let s = set_of(&[(c(0), c(10))]);
+    assert_eq!(s.complement(c(0), c(10)), Vec::new());
+    assert_eq!(s.complement(o(4), o(4)), Vec::new());
+
+    let empty = IntervalSet::new();
+    assert_eq!(empty.complement(c(0), c(10)), vec![(c(0), c(10))]);
+    assert_eq!(empty.complement(c(5), c(1)), Vec::new());
+}
+
+#[test]
+fn display_formats_canonical_form() {
+    let s = set_of(&[(c(1), o(3)), (o(4), c(5)), (c(7), c(7))]);
+    assert_eq!(format!("{}", s), "{[1,3), (4,5], [7,7]}");
+
+    let s = set_of(&[(o(-3), c(0))]);
+    assert_eq!(format!("{}", s), "{(-3,0]}");
+
+    let s = IntervalSet::new();
+    assert_eq!(format!("{}", s), "{}");
+}
+
+#[test]
+fn bound_accessors_report_value_and_kind() {
+    assert_eq!(c(4).value(), 4);
+    assert!(c(4).is_closed());
+    assert_eq!(o(-4).value(), -4);
+    assert!(!o(-4).is_closed());
+}
+
+#[test]
+fn workload_with_downward_sweep_finishes_quickly() {
+    let mut state: u64 = 0x9E37_79B9_7F4A_7C15;
+    let mut next = move || {
+        state = state
+            .wrapping_mul(6364136223846793005)
+            .wrapping_add(1442695040888963407);
+        state >> 33
+    };
+
+    let n: usize = 300_000;
+    let mut prev: Vec<(Bound, Bound)> = Vec::with_capacity(n);
+    let mut set = IntervalSet::new();
+
+    let start = Instant::now();
+    for i in 0..n {
+        let base = 1_000_000_000i64 - (i as i64) * 3333;
+        let jitter = (next() % 1000) as i64;
+        let lo_v = base + jitter;
+        let len = (next() % 1001) as i64;
+        let hi_v = lo_v + len;
+        let lo = if next() % 2 == 0 { c(lo_v) } else { o(lo_v) };
+        let hi = if next() % 2 == 0 { c(hi_v) } else { o(hi_v) };
+        set.insert(lo, hi);
+        prev.push((lo, hi));
+        if i >= 1 {
+            let (plo, phi) = prev[i - 1];
+            set.remove(plo, phi);
+        }
+        let probe = (next() % 1_000_000_001) as f64;
+        let _ = set.contains(probe);
+    }
+    let elapsed = start.elapsed();
+
+    set.insert(c(-5), c(-5));
+    assert!(set.contains(-5.0));
+    assert!(elapsed.as_secs_f64() < 3.0, "took {:?}", elapsed);
+}

