@@ -0,0 +1,98 @@
+use romankit::{from_roman, to_roman, RomanError};
+
+const ALPHABET: [char; 7] = ['I', 'V', 'X', 'L', 'C', 'D', 'M'];
+
+fn all_strings_up_to(max_len: usize) -> Vec<String> {
+    let mut out = vec![String::new()];
+    let mut frontier = vec![String::new()];
+    for _ in 0..max_len {
+        let mut next = Vec::new();
+        for prefix in &frontier {
+            for &c in &ALPHABET {
+                let mut s = prefix.clone();
+                s.push(c);
+                next.push(s);
+            }
+        }
+        out.extend(next.iter().cloned());
+        frontier = next;
+    }
+    out
+}
+
+#[test]
+fn to_roman_renders_canonical_numerals_for_valid_range() {
+    assert_eq!(to_roman(1).unwrap(), "I");
+    assert_eq!(to_roman(4).unwrap(), "IV");
+    assert_eq!(to_roman(19).unwrap(), "XIX");
+    assert_eq!(to_roman(1994).unwrap(), "MCMXCIV");
+    assert_eq!(to_roman(3999).unwrap(), "MMMCMXCIX");
+    assert!(!matches!(to_roman(0), Ok(_)));
+}
+
+#[test]
+fn to_roman_rejects_out_of_range_values() {
+    assert!(matches!(to_roman(0), Err(RomanError::OutOfRange)));
+    assert!(matches!(to_roman(4000), Err(RomanError::OutOfRange)));
+    assert!(matches!(to_roman(u32::MAX), Err(RomanError::OutOfRange)));
+    assert!(!matches!(to_roman(4000), Ok(_)));
+}
+
+#[test]
+fn from_roman_parses_subtractive_endings() {
+    assert_eq!(from_roman("IV").unwrap(), 4);
+    assert_eq!(from_roman("XIX").unwrap(), 19);
+    assert_eq!(from_roman("MCMXCIV").unwrap(), 1994);
+    assert_ne!(from_roman("IV").unwrap(), 6);
+}
+
+#[test]
+fn from_roman_round_trips_every_valid_number() {
+    for n in 1..=3999u32 {
+        let s = to_roman(n).unwrap();
+        assert_eq!(from_roman(&s).unwrap(), n);
+    }
+}
+
+#[test]
+fn from_roman_accepts_only_exact_canonical_forms() {
+    for s in all_strings_up_to(4) {
+        match from_roman(&s) {
+            Ok(n) => assert_eq!(to_roman(n).unwrap(), s),
+            Err(e) => assert!(!matches!(e, RomanError::OutOfRange), "OutOfRange for {s:?}"),
+        }
+    }
+}
+
+#[test]
+fn from_roman_rejects_empty_string() {
+    assert!(matches!(from_roman(""), Err(RomanError::Empty)));
+    assert!(!matches!(from_roman(""), Ok(_)));
+}
+
+#[test]
+fn from_roman_reports_first_invalid_character() {
+    assert!(matches!(from_roman("xiv"), Err(RomanError::InvalidChar('x'))));
+    assert!(matches!(from_roman("X V"), Err(RomanError::InvalidChar(' '))));
+    assert!(matches!(from_roman("IIZXq"), Err(RomanError::InvalidChar('Z'))));
+    assert!(matches!(from_roman("IIIIx"), Err(RomanError::InvalidChar('x'))));
+}
+
+#[test]
+fn from_roman_rejects_non_canonical_forms() {
+    assert!(matches!(from_roman("IIII"), Err(RomanError::NonCanonical)));
+    assert!(matches!(from_roman("IC"), Err(RomanError::NonCanonical)));
+    assert!(matches!(from_roman("VX"), Err(RomanError::NonCanonical)));
+    assert!(matches!(from_roman("MMMM"), Err(RomanError::NonCanonical)));
+    assert!(matches!(from_roman("IIV"), Err(RomanError::NonCanonical)));
+    assert!(matches!(from_roman("XM"), Err(RomanError::NonCanonical)));
+    assert!(!matches!(from_roman("MMMM"), Ok(_)));
+}
+
+#[test]
+fn from_roman_never_returns_out_of_range() {
+    for s in ["MMMM", "MMMMM", "MMMMCMXCIX", "MMMMDCCCLXXXVIII"] {
+        assert!(!matches!(from_roman(s), Err(RomanError::OutOfRange)));
+        assert!(matches!(from_roman(s), Err(RomanError::NonCanonical)));
+    }
+}
