diff --git a/tests/loki_wall_shape.rs b/tests/loki_wall_shape.rs
new file mode 100644
index 0000000..bd8c57d
--- /dev/null
+++ b/tests/loki_wall_shape.rs
@@ -0,0 +1,143 @@
+use shapekit::shape::Shape;
+use shapekit::{Shape as RootShape, ShapeError};
+
+fn close(x: f64, y: f64) -> bool {
+    (x - y).abs() < 1e-9
+}
+
+#[test]
+fn root_reexports_match_shape_module() {
+    let s: RootShape = Shape::Circle { r: 1.0 };
+    assert_eq!(s, RootShape::Circle { r: 1.0 });
+    let e: ShapeError = ShapeError::NegativeDimension;
+    assert_eq!(e, shapekit::shape::ShapeError::NegativeDimension);
+    assert_ne!(e, ShapeError::InvalidTriangle);
+}
+
+#[test]
+fn parse_is_case_insensitive_and_maps_aliases() {
+    assert_eq!(Shape::parse("CIRCLE", &[2.0]), Ok(Shape::Circle { r: 2.0 }));
+    assert_eq!(Shape::parse("Rect", &[2.0, 3.0]), Ok(Shape::Rect { w: 2.0, h: 3.0 }));
+    assert_eq!(Shape::parse("RECTANGLE", &[2.0, 3.0]), Ok(Shape::Rect { w: 2.0, h: 3.0 }));
+    assert_eq!(Shape::parse("Square", &[4.0]), Ok(Shape::Rect { w: 4.0, h: 4.0 }));
+    assert_eq!(
+        Shape::parse("triangle", &[3.0, 4.0, 5.0]),
+        Ok(Shape::Triangle { a: 3.0, b: 4.0, c: 5.0 })
+    );
+    assert!(Shape::parse("rect", &[2.0]).is_err());
+}
+
+#[test]
+fn parse_error_messages_and_check_order() {
+    let unknown = Shape::parse("HexAgon", &[1.0]);
+    assert_eq!(unknown, Err(ShapeError::UnknownKind("HexAgon".to_string())));
+    assert_eq!(unknown.unwrap_err().to_string(), "unknown shape kind: HexAgon");
+
+    assert_eq!(
+        Shape::parse("circle", &[1.0, 2.0]),
+        Err(ShapeError::WrongParamCount { expected: 1, got: 2 })
+    );
+    assert_eq!(
+        ShapeError::WrongParamCount { expected: 1, got: 2 }.to_string(),
+        "expected 1 params, got 2"
+    );
+
+    assert_eq!(Shape::parse("circle", &[-1.0]), Err(ShapeError::NegativeDimension));
+    assert_eq!(
+        ShapeError::NegativeDimension.to_string(),
+        "dimensions must be non-negative"
+    );
+
+    assert_eq!(
+        Shape::parse("triangle", &[1.0, 1.0, 3.0]),
+        Err(ShapeError::InvalidTriangle)
+    );
+    assert_eq!(
+        ShapeError::InvalidTriangle.to_string(),
+        "sides do not form a triangle"
+    );
+
+    // unknown kind is checked before parameter count and sign
+    assert_eq!(
+        Shape::parse("hexagon", &[-1.0, 2.0]),
+        Err(ShapeError::UnknownKind("hexagon".to_string()))
+    );
+    // parameter count is checked before sign
+    assert_eq!(
+        Shape::parse("circle", &[-1.0, 2.0]),
+        Err(ShapeError::WrongParamCount { expected: 1, got: 2 })
+    );
+}
+
+#[test]
+fn degenerate_and_zero_shapes_are_valid() {
+    let deg = Shape::Triangle { a: 1.0, b: 2.0, c: 3.0 };
+    assert!(close(deg.area().unwrap(), 0.0));
+    assert!(close(deg.perimeter().unwrap(), 6.0));
+    assert_eq!(Shape::Circle { r: 0.0 }.area(), Ok(0.0));
+    assert_eq!(Shape::Rect { w: 0.0, h: 5.0 }.perimeter(), Ok(10.0));
+}
+
+#[test]
+fn area_and_perimeter_values() {
+    assert!(close(Shape::Circle { r: 1.0 }.area().unwrap(), std::f64::consts::PI));
+    assert!(close(Shape::Circle { r: 1.0 }.perimeter().unwrap(), 2.0 * std::f64::consts::PI));
+    assert!(close(Shape::Rect { w: 2.0, h: 3.0 }.area().unwrap(), 6.0));
+    assert!(close(Shape::Rect { w: 2.0, h: 3.0 }.perimeter().unwrap(), 10.0));
+    assert!(close(Shape::Triangle { a: 3.0, b: 4.0, c: 5.0 }.area().unwrap(), 6.0));
+    assert!(close(Shape::Triangle { a: 3.0, b: 4.0, c: 5.0 }.perimeter().unwrap(), 12.0));
+}
+
+#[test]
+fn direct_shapes_are_validated_with_negative_before_triangle() {
+    assert_eq!(
+        Shape::Rect { w: -1.0, h: 2.0 }.area(),
+        Err(ShapeError::NegativeDimension)
+    );
+    assert_eq!(
+        Shape::Rect { w: -1.0, h: 2.0 }.perimeter(),
+        Err(ShapeError::NegativeDimension)
+    );
+    // negative side is reported as NegativeDimension even though the inequality also fails
+    assert_eq!(
+        Shape::Triangle { a: -5.0, b: 1.0, c: 1.0 }.area(),
+        Err(ShapeError::NegativeDimension)
+    );
+    assert_eq!(
+        Shape::Triangle { a: 1.0, b: 1.0, c: 3.0 }.area(),
+        Err(ShapeError::InvalidTriangle)
+    );
+    assert_eq!(
+        Shape::Triangle { a: 1.0, b: 1.0, c: 3.0 }.perimeter(),
+        Err(ShapeError::InvalidTriangle)
+    );
+}
+
+#[test]
+fn free_functions_keep_string_errors_and_values() {
+    assert!(close(shapekit::area("rect", &[2.0, 3.0]).unwrap(), 6.0));
+    assert!(close(shapekit::perimeter("rectangle", &[2.0, 3.0]).unwrap(), 10.0));
+    assert!(close(shapekit::area::area("square", &[2.0]).unwrap(), 4.0));
+    assert!(close(shapekit::perimeter::perimeter("triangle", &[3.0, 4.0, 5.0]).unwrap(), 12.0));
+
+    assert_eq!(
+        shapekit::area::area("hexagon", &[1.0]),
+        Err("unknown shape kind: hexagon".to_string())
+    );
+    assert_eq!(
+        shapekit::area::area("rect", &[1.0]),
+        Err("expected 2 params, got 1".to_string())
+    );
+    assert_eq!(
+        shapekit::area::area("circle", &[-1.0]),
+        Err("dimensions must be non-negative".to_string())
+    );
+    assert_eq!(
+        shapekit::perimeter::perimeter("triangle", &[1.0, 1.0, 3.0]),
+        Err("sides do not form a triangle".to_string())
+    );
+    assert_eq!(
+        shapekit::perimeter::perimeter("triangle", &[-1.0, 1.0, 1.0]),
+        Err("dimensions must be non-negative".to_string())
+    );
+}

diff --git a/tests/loki_wall_stats.rs b/tests/loki_wall_stats.rs
