@@ -0,0 +1,125 @@
+use statkit::stats::{count, mean, median, percentile};
+use statkit::summary;
+
+const EPS: f64 = 1e-9;
+
+fn close(a: f64, b: f64) -> bool {
+    (a - b).abs() < EPS
+}
+
+#[test]
+fn summary_reports_interpolated_percentiles() {
+    assert_eq!(summary(&[1.0, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_ne!(summary(&[1.0, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.00 p90=3.00");
+}
+
+#[test]
+fn summary_is_independent_of_input_order() {
+    assert_eq!(summary(&[4.0, 1.0, 3.0, 2.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_eq!(summary(&[2.0, 4.0, 1.0, 3.0]), summary(&[1.0, 2.0, 3.0, 4.0]));
+}
+
+#[test]
+fn summary_empty_input_is_only_count() {
+    assert_eq!(summary(&[]), "n=0");
+    assert_ne!(summary(&[]), "n=0 mean=NaN p50=0.00 p90=0.00");
+}
+
+#[test]
+fn summary_all_nan_input_is_only_count() {
+    assert_eq!(summary(&[f64::NAN, f64::NAN]), "n=0");
+}
+
+#[test]
+fn summary_ignores_nan_values() {
+    assert_eq!(summary(&[1.0, f64::NAN, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_ne!(summary(&[1.0, f64::NAN, 2.0, 3.0, 4.0]), "n=5 mean=NaN p50=2.00 p90=3.00");
+}
+
+#[test]
+fn count_ignores_nan_values() {
+    assert_eq!(count(&[1.0, f64::NAN, 3.0]), 2);
+    assert_eq!(count(&[]), 0);
+    assert_eq!(count(&[f64::NAN]), 0);
+    assert_ne!(count(&[1.0, f64::NAN, 3.0]), 3);
+}
+
+#[test]
+fn mean_ignores_nan_and_is_none_when_undefined() {
+    assert!(close(mean(&[1.0, 2.0, 3.0, 4.0]).unwrap(), 2.5));
+    assert!(close(mean(&[1.0, f64::NAN, 2.0, 3.0, 4.0]).unwrap(), 2.5));
+    assert_eq!(mean(&[]), None);
+    assert_eq!(mean(&[f64::NAN, f64::NAN]), None);
+    assert!(!mean(&[f64::NAN, 1.0]).unwrap().is_nan());
+}
+
+#[test]
+fn median_is_percentile_fifty_and_ignores_nan() {
+    assert!(close(median(&[1.0, 2.0, 3.0, 4.0]).unwrap(), 2.5));
+    assert!(close(median(&[4.0, 2.0, 1.0, 3.0]).unwrap(), 2.5));
+    assert!(close(median(&[f64::NAN, 1.0, 2.0, 3.0, 4.0]).unwrap(), 2.5));
+    assert!(close(median(&[3.0, 1.0, 2.0]).unwrap(), 2.0));
+    assert_eq!(median(&[]), None);
+    assert_eq!(median(&[f64::NAN]), None);
+    assert_ne!(median(&[1.0, 2.0, 3.0, 4.0]), Some(2.0));
+}
+
+#[test]
+fn percentile_uses_linear_interpolation_between_closest_ranks() {
+    let v = [1.0, 2.0, 3.0, 4.0];
+    assert!(close(percentile(&v, 90.0).unwrap(), 3.7));
+    assert!(close(percentile(&[10.0, 20.0, 30.0], 25.0).unwrap(), 15.0));
+    assert_ne!(percentile(&v, 90.0), Some(3.0));
+}
+
+#[test]
+fn percentile_endpoints_are_min_and_max() {
