@@ -0,0 +1,82 @@
+use stockkit::{Inventory, Order, ReserveError};
+
+#[test]
+fn quantities_by_sku_sums_sorts_and_drops_zero() {
+    let order = Order::new("o")
+        .with_line("pear", 2)
+        .with_line("apple", 1)
+        .with_line("pear", 3)
+        .with_line("fig", 0);
+    assert_eq!(
+        order.quantities_by_sku(),
+        vec![("apple".to_string(), 1), ("pear".to_string(), 5)]
+    );
+}
+
+#[test]
+fn reserve_reduces_available_but_not_on_hand() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 5);
+    let id = inv.reserve(&Order::new("o").with_line("apple", 3)).unwrap();
+    assert_eq!(inv.available("apple"), 2);
+    assert_eq!(inv.on_hand("apple"), 5);
+    inv.release(id).unwrap();
+    assert_eq!(inv.available("apple"), 5);
+    assert_eq!(inv.release(id), Err(ReserveError::UnknownReservation));
+}
+
+#[test]
+fn commit_drops_on_hand_and_ends_hold() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 5);
+    let id = inv.reserve(&Order::new("o").with_line("apple", 3)).unwrap();
+    inv.commit(id).unwrap();
+    assert_eq!(inv.on_hand("apple"), 2);
+    assert_eq!(inv.available("apple"), 2);
+    assert_eq!(inv.commit(id), Err(ReserveError::UnknownReservation));
+    assert_eq!(inv.release(id), Err(ReserveError::UnknownReservation));
+}
+
+#[test]
+fn reserve_is_all_or_nothing_and_reports_first_failure_in_sku_order() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 1);
+    inv.add_stock("pear", 1);
+    let order = Order::new("o")
+        .with_line("pear", 5)
+        .with_line("apple", 2)
+        .with_line("kiwi", 1);
+    assert_eq!(
+        inv.reserve(&order),
+        Err(ReserveError::Insufficient {
+            sku: "apple".to_string(),
+            requested: 2,
+            available: 1,
+        })
+    );
+    assert_eq!(inv.available("pear"), 1);
+    assert_eq!(inv.available("apple"), 1);
+}
+
+#[test]
+fn unknown_sku_is_reported() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 1);
+    let order = Order::new("o").with_line("apple", 1).with_line("kiwi", 1);
+    assert_eq!(
+        inv.reserve(&order),
+        Err(ReserveError::UnknownSku("kiwi".to_string()))
+    );
+    assert_eq!(inv.available("apple"), 1);
+}
+
+#[test]
+fn ids_are_never_reused_and_empty_order_holds_nothing() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 1);
+    let a = inv.reserve(&Order::new("o")).unwrap();
+    inv.release(a).unwrap();
+    let b = inv.reserve(&Order::new("p").with_line("apple", 1)).unwrap();
+    assert_ne!(a, b);
+    assert_eq!(inv.available("apple"), 0);
+}

