+  expect(cartTotal(small, "")).toBe(2899);
+});
+
+test("SAVE10 takes 10% off the subtotal, shipping still charged", () => {
+  expect(cartTotal(small, "SAVE10")).toBe(2160 + 499);
+});
+
+test("SAVE10 rounds the discount to the nearest cent", () => {
+  const odd = [{ sku: "pen", priceCents: 999, qty: 1 }]; // 10% of 999 = 99.9 -> 100
+  expect(cartTotal(odd, "SAVE10")).toBe(899 + 499);
+});
+
+test("FLAT5 takes 500 cents off the subtotal", () => {
+  expect(cartTotal(small, "FLAT5")).toBe(1900 + 499);
+});
